/// <summary>
/// One standard D365 counting reason code (InventCountingReasonCode) for the supervisor picker.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountReasonCode
{
    str code;
    str description;

}

Method.Source:
[DataMemberAttribute('Code')]
public str parmCode(str _value = code)
{
    code = _value;
    return code;
}

[DataMemberAttribute('Description')]
public str parmDescription(str _value = description)
{
    description = _value;
    return description;
}
